"""
This file is used to include functions and operations for the Notifications window
"""

from pyjab.jabelement import JABElement
from interops.libraries.mim.interactions.objects import mim_objects

from interops.libraries.mim.common.logger import mLog

def get_notifications_popup(from_node:JABElement, wait_seconds: int = 0):
    notification_label = from_node.find_element_by_xpath(mim_objects.notification_label_xpath) if wait_seconds == 0 else from_node.wait_for_element(value=mim_objects.notification_label_xpath, timeout=wait_seconds)
    return notification_label.nth_parent(3) if notification_label else None

def acknowledge_notification(notification_dialog, name = "OK"):
    button_xpath = ""
    button_name = name.lower()
    if notification_dialog:
        if button_name == "ok":
            button_xpath = mim_objects.notification_ok_button_xpath
        elif button_name == "no":
            button_xpath = mim_objects.notification_no_button_xpath
        elif button_name == "close":
            button_xpath = mim_objects.notification_close_button_xpath
        elif button_name == "dismiss":
            button_xpath = mim_objects.notification_dismiss_button_xpath
        else:
            button_xpath = f"/push button[@name='{name}']"

        notification_button = notification_dialog.find_element_by_xpath(button_xpath) if button_xpath else None
        if notification_button:
            mLog(f"Clicked '{notification_button.name}' button")
            notification_button.click(True) #.click()
            return True
    return False
